      "fieldConfig": {
        "defaults": {
          "unit": "short",
          "color": {
            "mode": "thresholds"
          },
          "decimals": 0,
          "thresholds": {
            "mode": "absolute",
            "steps": [
              {
                "color": "#e15759",
                "value": null
              },
              {
                "color": "#f28e2b",
                "value": 1
              },
              {
                "color": "#59a14f",
